/**
 * The shape of the pinned SimulationCraft item-use-effect artifact, and a
 * runtime validator for it.
 *
 * Generated by `scripts/authority/extract-simc-item-effects.mjs` from one exact
 * SimulationCraft commit and committed. Nothing here reaches the network.
 *
 * THE ONE FACT THIS DATA EXISTS FOR
 *
 * Whether an equipped item has an ON_USE effect. `use_item_t::init` looks for
 * `SPECIAL_EFFECT_USE` and, finding none, sets `background = true` — so an
 * ON_EQUIP-only trinket produces no selectable action at all. That is a
 * STRUCTURAL fact about the profile, and it is emphatically not "the item is on
 * cooldown". Conflating those two would turn "this player cannot use that" into
 * "this player has not used that yet".
 *
 *     ITEM_SPELLTRIGGER_ON_USE   = 0
 *     ITEM_SPELLTRIGGER_ON_EQUIP = 1
 *
 * TWO EPISTEMIC GRADES
 *
 * `items[].*` are machine-extracted DBC rows. `actionSemantics` is a human
 * reading C++ — what SimulationCraft DOES with those rows — and carries the
 * measured hash of the module it was read from, because a change there alters
 * behaviour without touching a single DBC value.
 *
 * IDENTITY IS THE NUMBER
 *
 * `displayNameEn` exists so a human reading a debug dump recognises the row. The
 * extractor checks it to catch a mis-read row, but nothing matches on it at
 * runtime — Warcraft Logs gear carries item ids, and that is what is compared.
 */

/** The artifact schema version this build understands. */
export const SUPPORTED_ITEM_EFFECT_ARTIFACT_VERSION = 1;

/** `item_spell_trigger_type`, engine/dbc/data_enums.hh. */
export const TRIGGER_ON_USE = 0;

/**
 * `inventory_type` for a trinket.
 *
 * The ONE inventory type M5-C3c2 dispatches on: the pinned `items` list
 * addresses exactly two slots, `trinket1` and `trinket2`. A slot resolver may
 * claim a gear entry occupies one of them only if its pinned row says trinket,
 * which is what turns "the gear array is in slot order" from a reading into a
 * checked fact.
 */
export const INVENTORY_TYPE_TRINKET = 12;

export const ITEM_EFFECT_UNITS = "MILLISECONDS";
export const ITEM_DATA_METHOD = "MACHINE_EXTRACTED_DBC_RECORD";
export const ACTION_SEMANTICS_METHOD = "HAND_REVIEWED_CPP_ACTION_SEMANTICS";

export interface ItemEffectArtifactSource {
  readonly path: string;
  readonly sha256: string;
  readonly byteLength: number;
}

export interface ItemEffectArtifactProvenance {
  readonly repository: string;
  readonly commitSha: string;
  readonly sources: readonly ItemEffectArtifactSource[];
  readonly clientDataWowVersion: string;
  readonly clientDataHotfixDate: string;
  readonly clientDataHotfixBuild: number;
  readonly clientDataHotfixHash: string;
  readonly itemDataMethod: typeof ITEM_DATA_METHOD;
  readonly triggerTypeSource: string;
  /**
   * Where `inventory_type` was found, and how that column was IDENTIFIED.
   *
   * `item_data.inc` has no field header, so the extractor locates the column by
   * requiring agreement with every anchor below rather than hard-coding an
   * offset that a new upstream member would silently shift. Recorded so the
   * identification can be re-run rather than trusted.
   */
  readonly inventoryTypeColumnIndex: number;
  readonly inventoryTypeIdentification: string;
  readonly inventoryTypeAnchors: readonly InventoryTypeAnchor[];
  readonly cooldownFieldUnits: typeof ITEM_EFFECT_UNITS;
  readonly extractedOn: string;
  readonly extractorVersion: number;
  readonly applicabilityNote: string;
}

/** One item whose inventory type is independently known, fixing the column. */
export interface InventoryTypeAnchor {
  readonly itemId: number;
  readonly inventoryType: number;
  /** The equipment slot the anchor corresponds to. Human-readable only. */
  readonly slot: string;
}

export interface ActionSemanticsCheck {
  readonly claim: string;
  readonly search: string;
  readonly finding: string;
}

export interface ItemActionSemantics {
  readonly method: typeof ACTION_SEMANTICS_METHOD;
  readonly sourcePath: string;
  readonly sourceSha256: string;
  readonly reviewedOn: string;
  readonly checks: readonly ActionSemanticsCheck[];
}

/** One raw item-effect row, verbatim. */
export interface ItemEffectRow {
  readonly effectId: number;
  readonly spellId: number;
  readonly effectIndex: number;
  readonly triggerType: number;
  readonly triggerName: string;
  readonly cooldownDurationMs: number;
  readonly cooldownGroupDurationMs: number;
}

/**
 * The ON_USE effect of an item, when it has one.
 *
 * `baseCooldownMs` is the DRIVER SPELL's cooldown, reached because the effect
 * row's own `cooldown_duration` is -1 — see the recorded action-semantics check.
 */
export interface ItemOnUseEffect {
  readonly effectSpellId: number;
  readonly displayNameEn: string;
  readonly baseCooldownMs: number;
  /** Recorded for traceability. The category cooldown obeys a DIFFERENT readiness rule. */
  readonly categoryCooldownMs: number;
  readonly baseGcdMs: number;
}

export interface ItemEffectIdentity {
  readonly itemId: number;
  /** Human-readable only. Never used for matching. */
  readonly displayNameEn: string;
  /** The APL token when the pinned list names this item, else `null`. */
  readonly simcToken: string | null;
  readonly why: string;
  /**
   * `inventory_type` from the item's own DBC row.
   *
   * Present so a SLOT answer can be CHECKED. `use_items,slots=trinket2` is only
   * meaningful if the item the profile reports in that slot is in fact a
   * trinket; without this field the slot mapping would be an assertion in a
   * comment. See `INVENTORY_TYPE_TRINKET`.
   */
  readonly inventoryType: number;
  readonly effects: readonly ItemEffectRow[];
  /** `null` means NO on-use action can be constructed for this item. */
  readonly onUseEffect: ItemOnUseEffect | null;
}

export interface ItemEffectArtifact {
  readonly artifactVersion: number;
  readonly datasetId: string;
  readonly artifactRevision: string;
  readonly provenance: ItemEffectArtifactProvenance;
  readonly actionSemantics: ItemActionSemantics;
  readonly items: readonly ItemEffectIdentity[];
}

/** Field names that must NOT appear on an item: each is decided per decision. */
export const FORBIDDEN_DERIVED_ITEM_KEYS = [
  "equipped",
  "applicable",
  "ready",
  "remainsMs",
  "onCooldown",
] as const;

export type ItemEffectArtifactValidationReason =
  | "NOT_AN_OBJECT"
  | "UNSUPPORTED_ARTIFACT_VERSION"
  | "MALFORMED_PROVENANCE"
  | "UNSUPPORTED_UNITS"
  | "MALFORMED_ACTION_SEMANTICS"
  | "CONFLATED_PROVENANCE_GRADES"
  | "MALFORMED_ITEMS"
  | "MALFORMED_ITEM"
  | "DUPLICATE_ITEM_ID";

export type ItemEffectArtifactValidation =
  | { readonly ok: true; readonly artifact: ItemEffectArtifact }
  | { readonly ok: false; readonly reason: ItemEffectArtifactValidationReason; readonly detail: string };

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
function str(record: Record<string, unknown>, key: string): string | null {
  const value = record[key];
  return typeof value === "string" && value.length > 0 ? value : null;
}
function positiveInt(record: Record<string, unknown>, key: string): number | null {
  const value = record[key];
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0 ? value : null;
}
function anyInt(record: Record<string, unknown>, key: string): number | null {
  const value = record[key];
  return typeof value === "number" && Number.isSafeInteger(value) ? value : null;
}
function invalid(reason: ItemEffectArtifactValidationReason, detail: string): ItemEffectArtifactValidation {
  return { ok: false, reason, detail };
}

function validateSources(value: unknown): readonly ItemEffectArtifactSource[] | null {
  if (!Array.isArray(value) || value.length === 0) return null;
  const sources: ItemEffectArtifactSource[] = [];
  for (const raw of value) {
    if (!isRecord(raw)) return null;
    const path = str(raw, "path");
    const sha256 = str(raw, "sha256");
    const byteLength = positiveInt(raw, "byteLength");
    if (path === null || sha256 === null || byteLength === null) return null;
    if (!/^[0-9a-f]{64}$/.test(sha256)) return null;
    sources.push({ path, sha256, byteLength });
  }
  return sources;
}

/**
 * The anchors, revalidated rather than trusted.
 *
 * `null` when fewer than two DISTINCT inventory types are present: agreement
 * across many identical values would identify nothing, so an anchor set that
 * cannot discriminate is not an anchor set.
 */
function validateInventoryTypeAnchors(value: unknown): readonly InventoryTypeAnchor[] | null {
  if (!Array.isArray(value) || value.length === 0) return null;
  const anchors: InventoryTypeAnchor[] = [];
  for (const raw of value) {
    if (!isRecord(raw)) return null;
    const itemId = positiveInt(raw, "itemId");
    const inventoryType = positiveInt(raw, "inventoryType");
    const slot = str(raw, "slot");
    if (itemId === null || inventoryType === null || slot === null) return null;
    anchors.push({ itemId, inventoryType, slot });
  }
  if (new Set(anchors.map((anchor) => anchor.inventoryType)).size < 2) return null;
  return anchors;
}

function validateProvenance(value: unknown): ItemEffectArtifactProvenance | "BAD_UNITS" | null {
  if (!isRecord(value)) return null;
  const repository = str(value, "repository");
  const commitSha = str(value, "commitSha");
  const clientDataWowVersion = str(value, "clientDataWowVersion");
  const clientDataHotfixDate = str(value, "clientDataHotfixDate");
  const clientDataHotfixHash = str(value, "clientDataHotfixHash");
  const triggerTypeSource = str(value, "triggerTypeSource");
  const extractedOn = str(value, "extractedOn");
  const applicabilityNote = str(value, "applicabilityNote");
  const clientDataHotfixBuild = positiveInt(value, "clientDataHotfixBuild");
  const extractorVersion = positiveInt(value, "extractorVersion");
  const sources = validateSources(value["sources"]);
  const inventoryTypeIdentification = str(value, "inventoryTypeIdentification");
  const inventoryTypeAnchors = validateInventoryTypeAnchors(value["inventoryTypeAnchors"]);
  const rawColumn = value["inventoryTypeColumnIndex"];
  const inventoryTypeColumnIndex =
    typeof rawColumn === "number" && Number.isSafeInteger(rawColumn) && rawColumn >= 0 ? rawColumn : null;

  if (
    inventoryTypeIdentification === null ||
    inventoryTypeAnchors === null ||
    inventoryTypeColumnIndex === null ||
    repository === null ||
    commitSha === null ||
    clientDataWowVersion === null ||
    clientDataHotfixDate === null ||
    clientDataHotfixHash === null ||
    triggerTypeSource === null ||
    extractedOn === null ||
    applicabilityNote === null ||
    clientDataHotfixBuild === null ||
    extractorVersion === null ||
    sources === null ||
    value["itemDataMethod"] !== ITEM_DATA_METHOD
  ) {
    return null;
  }
  if (!/^[0-9a-f]{40}$/.test(commitSha)) return null;
  if (value["cooldownFieldUnits"] !== ITEM_EFFECT_UNITS) return "BAD_UNITS";

  return {
    repository,
    commitSha,
    sources,
    clientDataWowVersion,
    clientDataHotfixDate,
    clientDataHotfixBuild,
    clientDataHotfixHash,
    itemDataMethod: ITEM_DATA_METHOD,
    triggerTypeSource,
    inventoryTypeColumnIndex,
    inventoryTypeIdentification,
    inventoryTypeAnchors,
    cooldownFieldUnits: ITEM_EFFECT_UNITS,
    extractedOn,
    extractorVersion,
    applicabilityNote,
  };
}

function validateActionSemantics(value: unknown): ItemActionSemantics | null {
  if (!isRecord(value)) return null;
  const sourcePath = str(value, "sourcePath");
  const sourceSha256 = str(value, "sourceSha256");
  const reviewedOn = str(value, "reviewedOn");
  if (
    value["method"] !== ACTION_SEMANTICS_METHOD ||
    sourcePath === null ||
    sourceSha256 === null ||
    reviewedOn === null
  ) {
    return null;
  }
  if (!/^[0-9a-f]{64}$/.test(sourceSha256)) return null;
  const rawChecks = value["checks"];
  if (!Array.isArray(rawChecks) || rawChecks.length === 0) return null;
  const checks: ActionSemanticsCheck[] = [];
  for (const raw of rawChecks) {
    if (!isRecord(raw)) return null;
    const claim = str(raw, "claim");
    const search = str(raw, "search");
    const finding = str(raw, "finding");
    if (claim === null || search === null || finding === null) return null;
    checks.push({ claim, search, finding });
  }
  return { method: ACTION_SEMANTICS_METHOD, sourcePath, sourceSha256, reviewedOn, checks };
}

function validateEffects(value: unknown): readonly ItemEffectRow[] | null {
  if (!Array.isArray(value)) return null;
  const effects: ItemEffectRow[] = [];
  for (const raw of value) {
    if (!isRecord(raw)) return null;
    const effectId = positiveInt(raw, "effectId");
    const spellId = positiveInt(raw, "spellId");
    const effectIndex = anyInt(raw, "effectIndex");
    const triggerType = anyInt(raw, "triggerType");
    const triggerName = str(raw, "triggerName");
    const cooldownDurationMs = anyInt(raw, "cooldownDurationMs");
    const cooldownGroupDurationMs = anyInt(raw, "cooldownGroupDurationMs");
    if (
      effectId === null ||
      spellId === null ||
      effectIndex === null ||
      triggerType === null ||
      triggerName === null ||
      cooldownDurationMs === null ||
      cooldownGroupDurationMs === null
    ) {
      return null;
    }
    effects.push({
      effectId,
      spellId,
      effectIndex,
      triggerType,
      triggerName,
      cooldownDurationMs,
      cooldownGroupDurationMs,
    });
  }
  return effects;
}

function validateOnUse(value: unknown, effects: readonly ItemEffectRow[]): ItemOnUseEffect | null | "BAD" {
  if (value === null) {
    // Consistency: claiming no ON_USE while carrying an ON_USE row would make
    // the structural applicability answer disagree with its own evidence.
    return effects.some((effect) => effect.triggerType === TRIGGER_ON_USE) ? "BAD" : null;
  }
  if (!isRecord(value)) return "BAD";
  const effectSpellId = positiveInt(value, "effectSpellId");
  const displayNameEn = str(value, "displayNameEn");
  const baseCooldownMs = positiveInt(value, "baseCooldownMs");
  const categoryCooldownMs = anyInt(value, "categoryCooldownMs");
  const baseGcdMs = anyInt(value, "baseGcdMs");
  if (
    effectSpellId === null ||
    displayNameEn === null ||
    baseCooldownMs === null ||
    categoryCooldownMs === null ||
    baseGcdMs === null
  ) {
    return "BAD";
  }
  // The named effect must be one of the rows, and must actually be ON_USE.
  const row = effects.find((effect) => effect.spellId === effectSpellId);
  if (row === undefined || row.triggerType !== TRIGGER_ON_USE) return "BAD";
  return { effectSpellId, displayNameEn, baseCooldownMs, categoryCooldownMs, baseGcdMs };
}

export function validateItemEffectArtifact(value: unknown): ItemEffectArtifactValidation {
  if (!isRecord(value)) return invalid("NOT_AN_OBJECT", "artifact root is not an object");

  if (value["artifactVersion"] !== SUPPORTED_ITEM_EFFECT_ARTIFACT_VERSION) {
    return invalid(
      "UNSUPPORTED_ARTIFACT_VERSION",
      `artifactVersion ${String(value["artifactVersion"])} is not ${SUPPORTED_ITEM_EFFECT_ARTIFACT_VERSION}`,
    );
  }
  const datasetId = str(value, "datasetId");
  const artifactRevision = str(value, "artifactRevision");
  if (datasetId === null || artifactRevision === null) {
    return invalid("NOT_AN_OBJECT", "artifact header fields are missing or malformed");
  }

  const provenance = validateProvenance(value["provenance"]);
  if (provenance === "BAD_UNITS") {
    return invalid("UNSUPPORTED_UNITS", `provenance.cooldownFieldUnits must be '${ITEM_EFFECT_UNITS}'`);
  }
  if (provenance === null) {
    return invalid("MALFORMED_PROVENANCE", "provenance is incomplete or a hash is not a hash");
  }

  const actionSemantics = validateActionSemantics(value["actionSemantics"]);
  if (actionSemantics === null) {
    return invalid("MALFORMED_ACTION_SEMANTICS", "the hand-reviewed action semantics are unusable");
  }
  if (
    String(provenance.itemDataMethod) === String(ACTION_SEMANTICS_METHOD) ||
    String(actionSemantics.method) === String(ITEM_DATA_METHOD)
  ) {
    return invalid(
      "CONFLATED_PROVENANCE_GRADES",
      "a hand-reviewed claim is labelled as machine extraction or vice versa",
    );
  }

  const raws = value["items"];
  if (!Array.isArray(raws) || raws.length === 0) {
    return invalid("MALFORMED_ITEMS", "items is not a non-empty array");
  }

  const items: ItemEffectIdentity[] = [];
  const seen = new Set<number>();
  for (let index = 0; index < raws.length; index += 1) {
    const raw = raws[index];
    if (!isRecord(raw)) return invalid("MALFORMED_ITEM", `items[${index}] is not an object`);
    for (const forbidden of FORBIDDEN_DERIVED_ITEM_KEYS) {
      if (forbidden in raw) {
        return invalid(
          "MALFORMED_ITEM",
          `items[${index}] stores '${forbidden}'; that is decided per decision, never baked into the dataset`,
        );
      }
    }
    const itemId = positiveInt(raw, "itemId");
    const displayNameEn = str(raw, "displayNameEn");
    const why = str(raw, "why");
    const inventoryType = positiveInt(raw, "inventoryType");
    const effects = validateEffects(raw["effects"]);
    if (
      itemId === null ||
      displayNameEn === null ||
      why === null ||
      inventoryType === null ||
      effects === null
    ) {
      return invalid("MALFORMED_ITEM", `items[${index}] is missing required fields`);
    }
    const rawToken = raw["simcToken"];
    if (rawToken !== null && (typeof rawToken !== "string" || rawToken.length === 0)) {
      return invalid("MALFORMED_ITEM", `items[${index}] has an unusable simcToken`);
    }
    const onUse = validateOnUse(raw["onUseEffect"], effects);
    if (onUse === "BAD") {
      return invalid(
        "MALFORMED_ITEM",
        `items[${index}] has an on-use record that disagrees with its own effect rows`,
      );
    }
    if (seen.has(itemId)) return invalid("DUPLICATE_ITEM_ID", String(itemId));
    seen.add(itemId);

    items.push({
      itemId,
      displayNameEn,
      simcToken: rawToken as string | null,
      why,
      inventoryType,
      effects,
      onUseEffect: onUse,
    });
  }

  return {
    ok: true,
    artifact: { artifactVersion: 1, datasetId, artifactRevision, provenance, actionSemantics, items },
  };
}
